import csv
import json

# Load Alex Yoong's driverId
yoong_driver_id = 62

# Read races data
races = {}
with open('csv/races.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        races[row['raceId']] = row

# Read driverStandings for Alex Yoong
yoong_races = []
with open('csv/driverStandings.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['driverId'] == str(yoong_driver_id):
            race_id = row['raceId']
            if race_id in races:
                yoong_races.append({
                    'raceId': race_id,
                    'round': int(races[race_id]['round']),
                    'raceName': races[race_id]['name']
                })

# Filter for round < 20
filtered = [r for r in yoong_races if r['round'] < 20]
for r in filtered:
    print(f"RaceId: {r['raceId']}, Round: {r['round']}, Race Name: {r['raceName']}")
if not filtered:
    print('No races found with round < 20')

